 var htmlStart=title('Resolução · '+html(session.mode),'Questão '+q.num+' · '+emap[q.exam].year,'Prova: '+emap[q.exam].program+' · Tipo '+emap[q.exam].type+' · enunciado original, sem reformulações',button('pause','Pausar','secondary'));
